using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace Tools;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool(Name = "fetch_data", ReadOnly = true),
     Description("Fetches data from an external API for the given resource path.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The API resource path to fetch (e.g. \"users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace Prompts;

[McpServerPromptType]
public sealed class SummarizePrompts
{
    [McpServerPrompt(Name = "summarize"),
     Description("Creates a prompt that asks the model to summarize the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences for the summary.")] int? maxSentences = null)
    {
        var constraint = maxSentences.HasValue
            ? $" Use no more than {maxSentences.Value} sentences."
            : string.Empty;

        return
        [
            new()
            {
                Role = Role.User,
                Content = new TextContentBlock
                {
                    Text = $"Please provide a concise summary of the following text.{constraint}\n\n{text}"
                }
            }
        ];
    }
}

